// ============================================================
//
//	OEPSS — EPSS Exploit Prioritizer
//	Author  : khaled.s.haddad
//	Website : owlsec.org
//	Language: Go (stdlib only) — OWL suite
//
//	Ranks a CVE backlog by real-world exploitation likelihood: FIRST EPSS
//	probability + percentile, CISA KEV (known exploited) overrides, CVSS
//	impact, policy buckets with SLAs, backlog exposure (expected number of
//	exploited CVEs, P(any)), 30-day EPSS history and threshold tuning
//	(coverage / efficiency against KEV). v1.1: CycloneDX / SPDX SBOM input
//	with VEX, asset context (--assets), scan diffs (--diff) and a
//	self-contained HTML report. Works offline from embedded
//	snapshots; --update / --fetch pull live data from FIRST and CISA.
//
// ============================================================
