//  SEVERITY / BUCKETS / POLICY
// ====================================================================

const (
	SevCritical = "CRITICAL"
	SevHigh     = "HIGH"
	SevMedium   = "MEDIUM"
	SevLow      = "LOW"
	SevInfo     = "INFO"
)

const (
	BucketActNow    = "act-now"
	BucketUrgent    = "urgent"
	BucketScheduled = "scheduled"
	BucketDeferred  = "deferred"
	BucketUnknown   = "unknown"
)

var bucketOrder = []string{BucketActNow, BucketUrgent, BucketScheduled, BucketDeferred, BucketUnknown}
var bucketRank = map[string]int{BucketActNow: 5, BucketUrgent: 4, BucketScheduled: 3, BucketDeferred: 2, BucketUnknown: 1}

func bucketSeverity(b string) string {
	switch b {
	case BucketActNow:
		return SevCritical
	case BucketUrgent:
		return SevHigh
	case BucketScheduled:
		return SevMedium
	case BucketDeferred:
		return SevLow
	}
	return SevInfo
}

func bucketColor(b string) string {
	switch b {
	case BucketActNow:
		return col(b, R+B)
	case BucketUrgent:
		return col(b, R)
	case BucketScheduled:
		return col(b, OR)
	case BucketDeferred:
		return col(b, YLW)
	}
	return col(b, DIM)
}

// policy: a CVE lands in the first bucket whose EPSS or percentile trigger it
// meets. KEV membership (known exploited in the wild) overrides to act-now.
type policy struct {
	ActEPSS, UrgEPSS, SchEPSS float64
	ActPct, UrgPct, SchPct    float64
	KEVActNow                 bool
	SLA                       map[string]string
}

var pol = defaultPolicy()

func defaultPolicy() policy {
	return policy{
		ActEPSS: 0.5, UrgEPSS: 0.1, SchEPSS: 0.01,
		ActPct: 0.99, UrgPct: 0.95, SchPct: 0.80,
		KEVActNow: true,
		SLA: map[string]string{
			BucketActNow:    "Remediate within 24-48 hours — exploitation is active or highly likely.",
			BucketUrgent:    "Remediate within 7 days — elevated exploitation probability.",
			BucketScheduled: "Remediate within 30 days in the normal patch cycle.",
			BucketDeferred:  "Low exploitation probability — patch opportunistically, monitor EPSS.",
			BucketUnknown:   "No EPSS score in the loaded data — run with --fetch or --update.",
		},
	}
}

// parsePolicy reads "act=0.5,urgent=0.1,sched=0.01,act-pct=0.99,urgent-pct=0.95,sched-pct=0.8,kev=on".
func parsePolicy(s string) (policy, error) {
	p := defaultPolicy()
	for _, part := range strings.Split(s, ",") {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		k, v, ok := strings.Cut(part, "=")
		if !ok {
			return p, fmt.Errorf("policy term %q needs key=value", part)
		}
		k = strings.ToLower(strings.TrimSpace(k))
		if k == "kev" {
			p.KEVActNow = v == "on" || v == "1" || v == "true"
			continue
		}
		f, err := strconv.ParseFloat(strings.TrimSpace(v), 64)
		if err != nil || f < 0 || f > 1 {
			return p, fmt.Errorf("policy %s=%s: want a number in 0..1", k, v)
		}
		switch k {
		case "act", "act-now":
			p.ActEPSS = f
		case "urgent":
			p.UrgEPSS = f
		case "sched", "scheduled":
			p.SchEPSS = f
		case "act-pct":
			p.ActPct = f
		case "urgent-pct":
			p.UrgPct = f
		case "sched-pct", "scheduled-pct":
			p.SchPct = f
		default:
			return p, fmt.Errorf("unknown policy key %q", k)
		}
	}
	if !(p.ActEPSS >= p.UrgEPSS && p.UrgEPSS >= p.SchEPSS) {
		return p, errors.New("policy thresholds must satisfy act ≥ urgent ≥ sched")
	}
	return p, nil
}

func (p policy) bucket(epss, pct float64, known, kev bool) (string, string) {
	if kev && p.KEVActNow {
		return BucketActNow, "CISA KEV (known exploited)"
	}
	if !known {
		return BucketUnknown, "no EPSS record"
	}
	switch {
	case epss >= p.ActEPSS:
		return BucketActNow, fmt.Sprintf("EPSS ≥ %.2f", p.ActEPSS)
	case pct >= p.ActPct:
		return BucketActNow, fmt.Sprintf("percentile ≥ %.0f%%", p.ActPct*100)
	case epss >= p.UrgEPSS:
		return BucketUrgent, fmt.Sprintf("EPSS ≥ %.2f", p.UrgEPSS)
	case pct >= p.UrgPct:
		return BucketUrgent, fmt.Sprintf("percentile ≥ %.0f%%", p.UrgPct*100)
	case epss >= p.SchEPSS:
		return BucketScheduled, fmt.Sprintf("EPSS ≥ %.2f", p.SchEPSS)
	case pct >= p.SchPct:
		return BucketScheduled, fmt.Sprintf("percentile ≥ %.0f%%", p.SchPct*100)
	}
	return BucketDeferred, "below all thresholds"
}

