var (
	epssDB     = map[string]epssEntry{}
	epssSource = "embedded snapshot"
	epssDate   = snapshotDate
	epssModel  = ""
)

func init() {
	for _, e := range epssSnapshot {
		epssDB[e.CVE] = e
	}
}

var reCVE = regexp.MustCompile(`(?i)\bCVE-(\d{4})-(\d{4,7})\b`)

// normCVE upper-cases and validates a CVE id ("" when it is not one).
func normCVE(s string) string {
	m := reCVE.FindStringSubmatch(strings.TrimSpace(s))
	if m == nil || len(m[0]) != len(strings.TrimSpace(s)) {
		return ""
	}
	return "CVE-" + m[1] + "-" + m[2]
}

func lookupEPSS(cve string) (epssEntry, bool) {
	e, ok := epssDB[strings.ToUpper(strings.TrimSpace(cve))]
	return e, ok
}

// maybeGunzip transparently inflates gzip data (EPSS ships as .csv.gz).
func maybeGunzip(data []byte) ([]byte, error) {
	if len(data) < 2 || data[0] != 0x1f || data[1] != 0x8b {
		return data, nil
	}
	zr, err := gzip.NewReader(bytes.NewReader(data))
	if err != nil {
		return nil, err
	}
	defer zr.Close()
	return io.ReadAll(io.LimitReader(zr, 512<<20))
}

// loadEPSSCSV parses the official EPSS CSV:
//
//	#model_version:v2025.03.14,score_date:2026-10-30T00:00:00+0000
//	cve,epss,percentile
//	CVE-1999-0001,0.0142,0.80
func loadEPSSCSV(data []byte, into map[string]epssEntry) (n int, date, model string, err error) {
	sc := bufio.NewScanner(bytes.NewReader(data))
	sc.Buffer(make([]byte, 1<<20), 1<<24)
	for sc.Scan() {
		ln := strings.TrimSpace(sc.Text())
		if ln == "" {
			continue
		}
		if strings.HasPrefix(ln, "#") {
			for _, part := range strings.Split(strings.TrimPrefix(ln, "#"), ",") {
				k, v, _ := strings.Cut(part, ":")
				switch strings.TrimSpace(k) {
				case "score_date":
					date = strings.TrimSpace(v)
					if len(date) >= 10 {
						date = date[:10]
					}
				case "model_version":
					model = strings.TrimSpace(v)
				}
			}
			continue
		}
		f := strings.Split(ln, ",")
		if len(f) < 3 {
			continue
		}
		cve := normCVE(f[0])
		if cve == "" {
			continue // header row
		}
		e, err1 := strconv.ParseFloat(strings.TrimSpace(f[1]), 64)
		p, err2 := strconv.ParseFloat(strings.TrimSpace(f[2]), 64)
		if err1 != nil || err2 != nil {
			continue
		}
		into[cve] = epssEntry{cve, e, p}
		n++
	}
	return n, date, model, sc.Err()
}

// firstResponse is the FIRST EPSS API shape (numbers arrive as strings).
type firstResponse struct {
	Status string `json:"status"`
	Total  int    `json:"total"`
	Data   []struct {
		CVE        string `json:"cve"`
		EPSS       string `json:"epss"`
		Percentile string `json:"percentile"`
		Date       string `json:"date"`
		Series     []struct {
			EPSS       string `json:"epss"`
			Percentile string `json:"percentile"`
			Date       string `json:"date"`
		} `json:"time-series"`
	} `json:"data"`
}

func loadEPSSJSON(data []byte, into map[string]epssEntry) (int, string, error) {
	var doc firstResponse
	if err := json.Unmarshal(data, &doc); err != nil {
		return 0, "", err
	}
	n, date := 0, ""
	for _, d := range doc.Data {
		e, err1 := strconv.ParseFloat(d.EPSS, 64)
		p, err2 := strconv.ParseFloat(d.Percentile, 64)
		cve := normCVE(d.CVE)
		if err1 != nil || err2 != nil || cve == "" {
			continue
		}
		into[cve] = epssEntry{cve, e, p}
		if d.Date > date {
			date = d.Date
		}
		n++
	}
	return n, date, nil
}

// loadEPSSFile loads CSV, CSV.gz or FIRST-API JSON and replaces the source label.
func loadEPSSFile(path string) (int, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return 0, err
	}
	data, err := maybeGunzip(raw)
	if err != nil {
		return 0, err
	}
	if t := bytes.TrimSpace(data); len(t) > 0 && t[0] == '{' {
		n, date, err := loadEPSSJSON(data, epssDB)
		if err == nil && n > 0 {
			epssSource, epssDate = filepath.Base(path), date
		}
		return n, err
	}
	fresh := map[string]epssEntry{}
	n, date, model, err := loadEPSSCSV(data, fresh)
	if err != nil {
		return n, err
	}
	if n == 0 {
		return 0, errors.New("no EPSS rows found (expected cve,epss,percentile)")
	}
	// a full daily file replaces the snapshot; a partial one is merged
	if n > 100000 {
		epssDB = fresh
	} else {
		for k, v := range fresh {
			epssDB[k] = v
		}
	}
	epssSource, epssModel = filepath.Base(path), model
	if date != "" {
		epssDate = date
	}
	return n, nil
}

