type kevEntry struct {
	CVE, Added, Due, Vendor, Product, Name string
	Ransomware                             bool
}

var (
	kevDB      = map[string]kevEntry{}
	kevSource  = "embedded snapshot"
	kevVersion = kevSnapshotVersion
)

func init() {
	for _, s := range kevSnapshot {
		f := strings.SplitN(s, "|", 6)
		if len(f) == 6 {
			kevDB[f[0]] = kevEntry{CVE: f[0], Added: f[1], Due: f[2], Ransomware: f[3] == "K", Vendor: f[4], Product: f[5]}
		}
	}
}

// loadKEVJSON parses the official CISA known_exploited_vulnerabilities.json.
func loadKEVJSON(data []byte) (map[string]kevEntry, string, error) {
	var doc struct {
		CatalogVersion  string `json:"catalogVersion"`
		Vulnerabilities []struct {
			CVE        string `json:"cveID"`
			Vendor     string `json:"vendorProject"`
			Product    string `json:"product"`
			Name       string `json:"vulnerabilityName"`
			Added      string `json:"dateAdded"`
			Due        string `json:"dueDate"`
			Ransomware string `json:"knownRansomwareCampaignUse"`
		} `json:"vulnerabilities"`
	}
	if err := json.Unmarshal(data, &doc); err != nil {
		return nil, "", err
	}
	if len(doc.Vulnerabilities) == 0 {
		return nil, "", errors.New("not a CISA KEV catalog (no vulnerabilities array)")
	}
	m := map[string]kevEntry{}
	for _, v := range doc.Vulnerabilities {
		if c := normCVE(v.CVE); c != "" {
			m[c] = kevEntry{CVE: c, Added: v.Added, Due: v.Due, Vendor: v.Vendor, Product: v.Product,
				Name: v.Name, Ransomware: strings.EqualFold(v.Ransomware, "Known")}
		}
	}
	return m, doc.CatalogVersion, nil
}

func loadKEVFile(path string) (int, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return 0, err
	}
	m, ver, err := loadKEVJSON(data)
	if err != nil {
		return 0, err
	}
	kevDB, kevSource, kevVersion = m, filepath.Base(path), ver
	return len(m), nil
}

// ====================================================================
//  ONLINE: FIRST API, daily EPSS file, CISA KEV  (opt-in: --fetch / --update)
// ====================================================================

const (
	firstAPI = "https://api.first.org/data/v1/epss"
	epssURL  = "https://epss.empiricalsecurity.com/epss_scores-current.csv.gz"
	kevURL   = "https://www.cisa.gov/sites/default/files/feeds/known_exploited_vulnerabilities.json"
)

var httpClient = &http.Client{Timeout: 90 * time.Second}

func httpGet(u string) ([]byte, error) {
	req, err := http.NewRequest("GET", u, nil)
	if err != nil {
		return nil, err
	}
	req.Header.Set("User-Agent", APPNAME+"/"+VERSION+" (+https://"+WEBSITE+")")
	resp, err := httpClient.Do(req)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	if resp.StatusCode != 200 {
		return nil, fmt.Errorf("%s: HTTP %d", u, resp.StatusCode)
	}
	return io.ReadAll(io.LimitReader(resp.Body, 256<<20))
}

// fetchEPSS asks the FIRST API for the given CVEs (100 per request) and merges
// the answers into epssDB. Returns how many CVEs came back scored.
func fetchEPSS(cves []string) (int, error) {
	got := 0
	for i := 0; i < len(cves); i += 100 {
		j := i + 100
		if j > len(cves) {
			j = len(cves)
		}
		q := url.Values{"cve": {strings.Join(cves[i:j], ",")}, "limit": {"100"}}
		data, err := httpGet(firstAPI + "?" + q.Encode())
		if err != nil {
			return got, err
		}
		n, date, err := loadEPSSJSON(data, epssDB)
		if err != nil {
			return got, err
		}
		got += n
		if date != "" {
			epssDate = date
			if !strings.Contains(epssSource, "FIRST API") {
				epssSource += " + FIRST API"
			}
		}
	}
	return got, nil
}

type histPoint struct {
	Date             string
	EPSS, Percentile float64
}

// fetchHistory returns the last ~30 daily EPSS scores for one CVE.
func fetchHistory(cve string) ([]histPoint, error) {
	q := url.Values{"cve": {cve}, "scope": {"time-series"}}
	data, err := httpGet(firstAPI + "?" + q.Encode())
	if err != nil {
		return nil, err
	}
	return parseHistory(data)
}

func parseHistory(data []byte) ([]histPoint, error) {
	var doc firstResponse
	if err := json.Unmarshal(data, &doc); err != nil {
		return nil, err
	}
	if len(doc.Data) == 0 {
		return nil, errors.New("CVE not scored by EPSS")
	}
	d := doc.Data[0]
	var pts []histPoint
	add := func(date, e, p string) {
		ef, err1 := strconv.ParseFloat(e, 64)
		pf, err2 := strconv.ParseFloat(p, 64)
		if err1 == nil && err2 == nil {
			pts = append(pts, histPoint{date, ef, pf})
		}
	}
	add(d.Date, d.EPSS, d.Percentile)
	for _, s := range d.Series {
		add(s.Date, s.EPSS, s.Percentile)
	}
	sort.Slice(pts, func(i, j int) bool { return pts[i].Date < pts[j].Date })
	// de-duplicate the current point if the series repeats it
	out := pts[:0]
	for i, p := range pts {
		if i == 0 || p.Date != pts[i-1].Date {
			out = append(out, p)
		}
	}
	return out, nil
}

func cacheDir() string {
	d, err := os.UserCacheDir()
	if err != nil {
		d = os.TempDir()
	}
	return filepath.Join(d, "owl", "oepss")
}

// updateCache downloads the daily EPSS file and the KEV catalog into the cache.
func updateCache() error {
	dir := cacheDir()
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	info("downloading daily EPSS scores …")
	ep, err := httpGet(epssURL)
	if err != nil {
		return err
	}
	if err := os.WriteFile(filepath.Join(dir, "epss_scores-current.csv.gz"), ep, 0o644); err != nil {
		return err
	}
	okMsg(fmt.Sprintf("EPSS file: %.1f MB", float64(len(ep))/(1<<20)))
	info("downloading CISA KEV catalog …")
	kv, err := httpGet(kevURL)
	if err != nil {
		return err
	}
	if _, _, err := loadKEVJSON(kv); err != nil {
		return err
	}
	if err := os.WriteFile(filepath.Join(dir, "known_exploited_vulnerabilities.json"), kv, 0o644); err != nil {
		return err
	}
	okMsg(fmt.Sprintf("KEV catalog: %.1f MB", float64(len(kv))/(1<<20)))
	return loadCache(true)
}

// loadCache loads previously downloaded data (silently unless verbose).
func loadCache(verbose bool) error {
	dir := cacheDir()
	var errs []string
	if p := filepath.Join(dir, "epss_scores-current.csv.gz"); fileExists(p) {
		if n, err := loadEPSSFile(p); err != nil {
			errs = append(errs, err.Error())
		} else {
			epssSource = "daily EPSS file (cache)"
			if verbose {
				okMsg(fmt.Sprintf("loaded %d EPSS scores dated %s", n, epssDate))
			}
		}
	}
	if p := filepath.Join(dir, "known_exploited_vulnerabilities.json"); fileExists(p) {
		if n, err := loadKEVFile(p); err != nil {
			errs = append(errs, err.Error())
		} else {
			kevSource = "CISA KEV feed (cache)"
			if verbose {
				okMsg(fmt.Sprintf("loaded %d KEV entries (catalog %s)", n, kevVersion))
			}
		}
	}
	if len(errs) > 0 {
		return errors.New(strings.Join(errs, "; "))
	}
	return nil
}

func fileExists(p string) bool { _, err := os.Stat(p); return err == nil }

