// ====================================================================
//  INPUT: extract CVEs from anything (lists, CSV, scanner JSON, reports)
// ====================================================================

type cveInput struct {
	CVE    string
	CVSS   float64  // <0 = unknown
	Count  int      // occurrences in the input
	Comps  []string // affected packages (SBOM / scanner JSON)
	Tokens []string // other words on the same line / scan target (asset matching)
	VEX    string   // CycloneDX analysis.state
}

// addUniq appends the values missing from dst (bounded, order kept).
func addUniq(dst []string, vals ...string) []string {
	for _, v := range vals {
		if v == "" || len(dst) >= 24 {
			continue
		}
		dup := false
		for _, d := range dst {
			if d == v {
				dup = true
				break
			}
		}
		if !dup {
			dst = append(dst, v)
		}
	}
	return dst
}

var reLineTok = regexp.MustCompile(`[^\s,;|"'()\[\]{}]+`)

// lineTokens: the non-CVE, non-numeric words of an input line — host names,
// packages, images — that an --assets rule can match.
func lineTokens(ln string) []string {
	var out []string
	for _, t := range reLineTok.FindAllString(ln, 12) {
		if reCVE.MatchString(t) || len(t) < 2 {
			continue
		}
		if _, err := strconv.ParseFloat(t, 64); err == nil {
			continue
		}
		out = addUniq(out, t)
	}
	return out
}

var (
	reCVSSKey = regexp.MustCompile(`(?i)(?:cvss|basescore|v3score)[a-z0-9_ .:"'{}\[\]-]{0,40}?(10(?:\.0)?|\d\.\d)\b`)
	reBareNum = regexp.MustCompile(`(?:^|[,;\t ])(10(?:\.0)?|\d\.\d)(?:$|[,;\t ])`)
)

// extractCVEs pulls every CVE id out of free text and keeps the highest CVSS
// seen on the same line (scanner exports: Trivy, Grype, Nessus CSV, OpenVAS…).
func extractCVEs(text string) []cveInput {
	idx := map[string]int{}
	var out []cveInput
	for _, ln := range strings.Split(text, "\n") {
		ms := reCVE.FindAllStringSubmatch(ln, -1)
		if len(ms) == 0 {
			continue
		}
		cvss := -1.0
		if m := reCVSSKey.FindStringSubmatch(ln); m != nil {
			cvss, _ = strconv.ParseFloat(m[1], 64)
		} else if len(ms) == 1 {
			rest := strings.Replace(ln, ms[0][0], " ", 1)
			if m := reBareNum.FindStringSubmatch(rest); m != nil {
				cvss, _ = strconv.ParseFloat(m[1], 64)
			}
		}
		toks := lineTokens(ln)
		for _, m := range ms {
			c := "CVE-" + m[1] + "-" + m[2]
			if i, ok := idx[c]; ok {
				out[i].Count++
				if cvss > out[i].CVSS {
					out[i].CVSS = cvss
				}
				out[i].Tokens = addUniq(out[i].Tokens, toks...)
				continue
			}
			idx[c] = len(out)
			out = append(out, cveInput{CVE: c, CVSS: cvss, Count: 1, Tokens: toks})
		}
	}
	return out
}

// reScoreKey names JSON fields that carry a CVSS base score.
var reScoreKey = regexp.MustCompile(`(?i)^(?:v3score|v3_score|v31score|v40score|basescore|base_score|cvss3?_?score|cvss_v3|score)$`)

// extractJSON understands structured scanner output (Trivy, Grype, OSV,
// Dependency-Track …): every object whose own string fields hold a CVE id
// gets the highest CVSS-like number found beneath it.
func extractJSON(data []byte) ([]cveInput, bool) {
	var doc any
	if err := json.Unmarshal(data, &doc); err != nil {
		return nil, false
	}
	idx := map[string]int{}
	var out []cveInput
	var maxScore func(v any) float64
	maxScore = func(v any) float64 {
		best := -1.0
		switch t := v.(type) {
		case map[string]any:
			for k, x := range t {
				if f, ok := x.(float64); ok && reScoreKey.MatchString(k) && f >= 0 && f <= 10 && f > best {
					best = f
				}
				if s := maxScore(x); s > best {
					best = s
				}
			}
		case []any:
			for _, x := range t {
				if s := maxScore(x); s > best {
					best = s
				}
			}
		}
		return best
	}
	// ctx carries the package / scan target of the enclosing objects down to
	// the vulnerability record (Trivy: PkgName on the record, Target on the
	// Result; Grype: artifact beside vulnerability; OSV: package).
	var walk func(v any, comp, target string)
	walk = func(v any, comp, target string) {
		switch t := v.(type) {
		case map[string]any:
			if c := pkgOf(t); c != "" {
				comp = c
			}
			if tg, ok := t["Target"].(string); ok && tg != "" {
				target = tg
			}
			var own []string
			for _, x := range t {
				if s, ok := x.(string); ok {
					if c := normCVE(s); c != "" {
						own = append(own, c)
					}
				}
			}
			if len(own) > 0 {
				sc := maxScore(t)
				for _, c := range own {
					if i, ok := idx[c]; ok {
						out[i].Count++
						if sc > out[i].CVSS {
							out[i].CVSS = sc
						}
						out[i].Comps = addUniq(out[i].Comps, comp)
						out[i].Tokens = addUniq(out[i].Tokens, target)
						continue
					}
					idx[c] = len(out)
					out = append(out, cveInput{CVE: c, CVSS: sc, Count: 1,
						Comps: addUniq(nil, comp), Tokens: addUniq(nil, target)})
				}
			}
			for _, x := range t {
				walk(x, comp, target)
			}
		case []any:
			for _, x := range t {
				walk(x, comp, target)
			}
		}
	}
	walk(doc, "", "")
	return out, len(out) > 0
}

// extractAny prefers SBOMs, then structured JSON, then line-based text.
func extractAny(data []byte) []cveInput {
	if t := bytes.TrimSpace(data); len(t) > 0 && (t[0] == '{' || t[0] == '[') {
		if in, _, ok := extractSBOM(t); ok {
			return in
		}
		if in, ok := extractJSON(t); ok {
			return in
		}
	}
	return extractCVEs(string(data))
}

// mergeInputs unions several extractions, keeping the highest CVSS.
func mergeInputs(sets ...[]cveInput) []cveInput {
	idx := map[string]int{}
	var out []cveInput
	for _, set := range sets {
		for _, c := range set {
			if i, ok := idx[c.CVE]; ok {
				out[i].Count += c.Count
				if c.CVSS > out[i].CVSS {
					out[i].CVSS = c.CVSS
				}
				out[i].Comps = addUniq(out[i].Comps, c.Comps...)
				out[i].Tokens = addUniq(out[i].Tokens, c.Tokens...)
				if out[i].VEX == "" {
					out[i].VEX = c.VEX
				}
				continue
			}
			idx[c.CVE] = len(out)
			out = append(out, c)
		}
	}
	return out
}

func cveIDs(in []cveInput) []string {
	ids := make([]string, len(in))
	for i, c := range in {
		ids[i] = c.CVE
	}
	return ids
}

// ====================================================================
//  PRIORITISATION ENGINE
// ====================================================================

type priorityRow struct {
	CVE        string   `json:"cve"`
	EPSS       float64  `json:"epss"`
	Percentile float64  `json:"percentile"`
	CVSS       float64  `json:"cvss"`
	CVSSSource string   `json:"cvss_source,omitempty"`
	Risk       float64  `json:"risk"`
	Known      bool     `json:"epss_known"`
	KEV        bool     `json:"kev"`
	KEVAdded   string   `json:"kev_added,omitempty"`
	KEVDue     string   `json:"kev_due,omitempty"`
	Ransomware bool     `json:"kev_ransomware,omitempty"`
	Product    string   `json:"product,omitempty"`
	Bucket     string   `json:"bucket"`
	Reason     string   `json:"reason"`
	Count      int      `json:"occurrences"`
	Components []string `json:"components,omitempty"`
	Asset      string   `json:"asset,omitempty"`     // matched --assets rule
	AssetAdj   int      `json:"asset_adj,omitempty"` // bucket steps it moved
	VEX        string   `json:"vex,omitempty"`       // SBOM analysis state
	tokens     []string
}

// vexClosed: VEX says the CVE does not affect this product (or is fixed);
// such rows stay listed but leave the exposure maths and the exit code.
func vexClosed(state string) bool {
	switch state {
	case "not_affected", "false_positive", "resolved", "resolved_with_pedigree", "fixed":
		return true
	}
	return false
}

// combinedRisk: exploitation probability scaled by impact (0..10). Without a
// CVSS score the probability alone ranks the item (epss × 10).
func combinedRisk(epss, cvss float64) float64 {
	if cvss < 0 {
		return epss * 10
	}
	return epss * cvss
}

func prioritize(inputs []cveInput, mode string) []priorityRow {
	rows := make([]priorityRow, 0, len(inputs))
	for _, in := range inputs {
		r := priorityRow{CVE: in.CVE, CVSS: in.CVSS, Count: in.Count, Components: in.Comps, VEX: in.VEX, tokens: in.Tokens}
		if r.Count == 0 {
			r.Count = 1
		}
		if r.CVSS >= 0 {
			r.CVSSSource = "input"
		} else if v, ok := knownCVSS[in.CVE]; ok {
			r.CVSS, r.CVSSSource = v, "built-in"
		}
		if e, ok := lookupEPSS(in.CVE); ok {
			r.Known, r.EPSS, r.Percentile = true, e.EPSS, e.Percentile
		}
		if k, ok := kevDB[in.CVE]; ok {
			r.KEV, r.KEVAdded, r.KEVDue, r.Ransomware = true, k.Added, k.Due, k.Ransomware
			r.Product = strings.TrimSpace(k.Vendor + " " + k.Product)
		}
		r.Risk = combinedRisk(r.EPSS, r.CVSS)
		r.Bucket, r.Reason = pol.bucket(r.EPSS, r.Percentile, r.Known, r.KEV)
		applyAsset(&r)
		if vexClosed(r.VEX) {
			r.Reason = "VEX " + r.VEX + " · " + r.Reason
		}
		rows = append(rows, r)
	}
	sortRows(rows, mode)
	return rows
}

func sortRows(rows []priorityRow, mode string) {
	sort.SliceStable(rows, func(i, j int) bool {
		a, b := rows[i], rows[j]
		switch mode {
		case "epss":
			return a.EPSS > b.EPSS
		case "percentile":
			return a.Percentile > b.Percentile
		case "risk":
			return a.Risk > b.Risk
		case "cvss":
			return a.CVSS > b.CVSS
		case "cve":
			return a.CVE < b.CVE
		}
		// "priority": open before VEX-closed, bucket, KEV ransomware, risk, EPSS
		if vexClosed(a.VEX) != vexClosed(b.VEX) {
			return !vexClosed(a.VEX)
		}
		if bucketRank[a.Bucket] != bucketRank[b.Bucket] {
			return bucketRank[a.Bucket] > bucketRank[b.Bucket]
		}
		if a.Ransomware != b.Ransomware {
			return a.Ransomware
		}
		if a.KEV != b.KEV {
			return a.KEV
		}
		if a.Risk != b.Risk {
			return a.Risk > b.Risk
		}
		return a.EPSS > b.EPSS
	})
}

var sortModes = map[string]bool{"priority": true, "epss": true, "percentile": true, "risk": true, "cvss": true, "cve": true}

// exposure summarises a backlog the way EPSS is meant to be read: the
// expected number of CVEs exploited in the next 30 days (Σ p) and the chance
// that at least one is (1 − Π(1 − p)).
type exposure struct {
	Total, Known, KEV, Ransomware int
	VEXClosed                     int `json:",omitempty"`
	Expected, PAny                float64
	Buckets                       map[string]int
	Score                         int
	Grade                         string
}

func computeExposure(rows []priorityRow) exposure {
	ex := exposure{Total: len(rows), Buckets: map[string]int{}}
	notAny := 1.0
	for _, r := range rows {
		if vexClosed(r.VEX) {
			ex.VEXClosed++
			continue
		}
		ex.Buckets[r.Bucket]++
		if r.Known {
			ex.Known++
			ex.Expected += r.EPSS
			notAny *= 1 - r.EPSS
		}
		if r.KEV {
			ex.KEV++
		}
		if r.Ransomware {
			ex.Ransomware++
		}
	}
	ex.PAny = 1 - notAny
	ex.Score = int(math.Round(100 * notAny))
	switch {
	case ex.KEV > 0:
		ex.Grade = "F"
	case ex.PAny < 0.01:
		ex.Grade = "A+"
	case ex.PAny < 0.05:
		ex.Grade = "A"
	case ex.PAny < 0.15:
		ex.Grade = "B"
	case ex.PAny < 0.35:
		ex.Grade = "C"
	case ex.PAny < 0.60:
		ex.Grade = "D"
	default:
		ex.Grade = "F"
	}
	if ex.KEV > 0 {
		ex.Score = 0
	}
	return ex
}

func gradeColor(g string) string {
	switch g {
	case "A+", "A":
		return col(g, GRN+B)
	case "B":
		return col(g, CY+B)
	case "C":
		return col(g, YLW+B)
	case "D":
		return col(g, OR+B)
	}
	return col(g, R+B)
}

// ====================================================================
//  ANALYTICS: distribution, trend vs snapshot, threshold tuning
// ====================================================================

var epssBands = []struct {
	Label  string
	Lo, Hi float64
}{
	{"≥ 0.90", 0.90, 1.01}, {"0.50–0.90", 0.50, 0.90}, {"0.10–0.50", 0.10, 0.50},
	{"0.01–0.10", 0.01, 0.10}, {"0.001–0.01", 0.001, 0.01}, {"< 0.001", -1, 0.001},
}

func printDistribution(values []float64) {
	counts := make([]int, len(epssBands))
	for _, v := range values {
		for i, b := range epssBands {
			if v >= b.Lo && v < b.Hi {
				counts[i]++
				break
			}
		}
	}
	max := 0
	for _, c := range counts {
		if c > max {
			max = c
		}
	}
	for i, b := range epssBands {
		share := 0.0
		if len(values) > 0 {
			share = float64(counts[i]) * 100 / float64(len(values))
		}
		fmt.Printf("  %s %8d %6.2f%%  %s\n", pad(b.Label, 11), counts[i], share, bar(counts[i], max, 36, CY))
	}
}

type trendRow struct {
	CVE           string
	Old, New, Del float64
}

// trendDiff compares the loaded dataset against the embedded snapshot.
func trendDiff(limit int) (risers, fallers []trendRow) {
	var all []trendRow
	for _, base := range epssSnapshot {
		cur, ok := epssDB[base.CVE]
		if !ok || cur.EPSS == base.EPSS {
			continue
		}
		all = append(all, trendRow{base.CVE, base.EPSS, cur.EPSS, cur.EPSS - base.EPSS})
	}
	sort.SliceStable(all, func(i, j int) bool { return all[i].Del > all[j].Del })
	for _, t := range all {
		if t.Del > 0 && len(risers) < limit {
			risers = append(risers, t)
		}
	}
	for i := len(all) - 1; i >= 0; i-- {
		if all[i].Del < 0 && len(fallers) < limit {
			fallers = append(fallers, all[i])
		}
	}
	return
}

type tuneRow struct {
	Threshold                    float64
	Flagged, Hits                int
	Effort, Coverage, Efficiency float64
	F1                           float64
}

// tuneThresholds measures each EPSS cut-off against KEV as ground truth:
// effort = share of all CVEs flagged, coverage = share of KEV CVEs caught,
// efficiency = share of flagged CVEs that are KEV (the EPSS paper's metrics).
func tuneThresholds() ([]tuneRow, int, int) {
	thresholds := []float64{0.001, 0.005, 0.01, 0.05, 0.1, 0.2, 0.3, 0.5, 0.7, 0.9}
	total, kevScored := len(epssDB), 0
	for c := range kevDB {
		if _, ok := epssDB[c]; ok {
			kevScored++
		}
	}
	rows := make([]tuneRow, len(thresholds))
	for i, t := range thresholds {
		rows[i].Threshold = t
	}
	for c, e := range epssDB {
		_, isKEV := kevDB[c]
		for i := range rows {
			if e.EPSS >= rows[i].Threshold {
				rows[i].Flagged++
				if isKEV {
					rows[i].Hits++
				}
			}
		}
	}
	for i := range rows {
		r := &rows[i]
		if total > 0 {
			r.Effort = float64(r.Flagged) / float64(total)
		}
		if kevScored > 0 {
			r.Coverage = float64(r.Hits) / float64(kevScored)
		}
		if r.Flagged > 0 {
			r.Efficiency = float64(r.Hits) / float64(r.Flagged)
		}
		if r.Coverage+r.Efficiency > 0 {
			r.F1 = 2 * r.Coverage * r.Efficiency / (r.Coverage + r.Efficiency)
		}
	}
	return rows, total, kevScored
}

// ====================================================================
//  REPORT + EXPORT
// ====================================================================

type Finding struct {
	ID       string  `json:"id"`
	Title    string  `json:"title"`
	Severity string  `json:"severity"`
	Bucket   string  `json:"bucket"`
	Detail   string  `json:"detail"`
	Remedy   string  `json:"remediation"`
	Score    float64 `json:"risk"`
}

type Report struct {
	Tool       string         `json:"tool"`
	Version    string         `json:"version"`
	Target     string         `json:"target"`
	Generated  string         `json:"generated"`
	EPSSSource string         `json:"epss_source"`
	EPSSDate   string         `json:"epss_date"`
	KEVSource  string         `json:"kev_source"`
	KEVVersion string         `json:"kev_version"`
	Policy     string         `json:"policy"`
	Exposure   exposure       `json:"exposure"`
	Counts     map[string]int `json:"counts"`
	Rows       []priorityRow  `json:"cves"`
	Findings   []Finding      `json:"findings"`
}

func policyString(p policy) string {
	return fmt.Sprintf("act=%.3g/pct%.0f urgent=%.3g/pct%.0f sched=%.3g/pct%.0f kev=%v",
		p.ActEPSS, p.ActPct*100, p.UrgEPSS, p.UrgPct*100, p.SchEPSS, p.SchPct*100, p.KEVActNow)
}

func rowDetail(r priorityRow) string {
	var b strings.Builder
	if r.Known {
		fmt.Fprintf(&b, "EPSS %.4f (%.1f%% chance of exploitation activity in 30 days, percentile %.1f).", r.EPSS, r.EPSS*100, r.Percentile*100)
	} else {
		b.WriteString("No EPSS score in the loaded data.")
	}
	if r.CVSS >= 0 {
		fmt.Fprintf(&b, " CVSS %.1f (%s); risk %.2f/10.", r.CVSS, r.CVSSSource, r.Risk)
	}
	if r.KEV {
		fmt.Fprintf(&b, " CISA KEV since %s, federal due date %s", r.KEVAdded, r.KEVDue)
		if r.Ransomware {
			b.WriteString(", used in ransomware campaigns")
		}
		if r.Product != "" {
			b.WriteString(" — " + r.Product)
		}
		b.WriteString(".")
	}
	if len(r.Components) > 0 {
		b.WriteString(" Affects: " + strings.Join(r.Components, ", ") + ".")
	}
	fmt.Fprintf(&b, " Bucket: %s (%s).", r.Bucket, r.Reason)
	return b.String()
}

func buildReport(target string, rows []priorityRow) Report {
	rep := Report{Tool: APPNAME, Version: VERSION, Target: target,
		Generated:  time.Now().UTC().Format(time.RFC3339),
		EPSSSource: epssSource, EPSSDate: epssDate, KEVSource: kevSource, KEVVersion: kevVersion,
		Policy: policyString(pol), Exposure: computeExposure(rows), Counts: map[string]int{},
		Rows: rows, Findings: []Finding{}}
	if rep.Rows == nil {
		rep.Rows = []priorityRow{}
	}
	for _, s := range []string{SevCritical, SevHigh, SevMedium, SevLow, SevInfo} {
		rep.Counts[s] = 0
	}
	for _, r := range rows {
		sev := bucketSeverity(r.Bucket)
		if vexClosed(r.VEX) {
			sev = SevInfo
		}
		rep.Counts[sev]++
		title := r.CVE + " — " + r.Bucket
		if r.KEV {
			title += " (KEV)"
		}
		rep.Findings = append(rep.Findings, Finding{ID: r.CVE, Title: title, Severity: sev, Bucket: r.Bucket,
			Detail: rowDetail(r), Remedy: pol.SLA[r.Bucket], Score: math.Round(r.Risk*100) / 100})
	}
	return rep
}

func exportTXT(r Report) string {
	var b strings.Builder
	fmt.Fprintf(&b, "%s v%s — %s\n", APPNAME, VERSION, TAGLINE)
	fmt.Fprintf(&b, "Target    : %s\nGenerated : %s\nEPSS      : %s (scores %s)\nKEV       : %s (catalog %s)\nPolicy    : %s\n",
		r.Target, r.Generated, r.EPSSSource, r.EPSSDate, r.KEVSource, r.KEVVersion, r.Policy)
	ex := r.Exposure
	fmt.Fprintf(&b, "Exposure  : %d CVEs, %d scored, %d KEV (%d ransomware); expected exploited (30d) %.2f; P(any) %.1f%%; grade %s\n",
		ex.Total, ex.Known, ex.KEV, ex.Ransomware, ex.Expected, ex.PAny*100, ex.Grade)
	b.WriteString(strings.Repeat("-", 66) + "\n")
	fmt.Fprintf(&b, "%-18s %-9s %-8s %-6s %-5s %-6s %-4s %s\n", "CVE", "BUCKET", "EPSS", "PCTL", "CVSS", "RISK", "KEV", "REASON")
	for _, x := range r.Rows {
		fmt.Fprintf(&b, "%-18s %-9s %-8s %-6s %-5s %-6.2f %-4s %s\n", x.CVE, x.Bucket, epssStr(x), pctStr(x), cvssStr(x.CVSS), x.Risk, kevStr(x), x.Reason)
	}
	return b.String()
}

func exportMD(r Report) string {
	var b strings.Builder
	fmt.Fprintf(&b, "# %s — CVE prioritisation\n\n", APPNAME)
	ex := r.Exposure
	fmt.Fprintf(&b, "- **Target:** %s\n- **Generated:** %s\n- **EPSS:** %s (scores %s)\n- **KEV:** %s (catalog %s)\n- **Policy:** `%s`\n",
		r.Target, r.Generated, r.EPSSSource, r.EPSSDate, r.KEVSource, r.KEVVersion, r.Policy)
	fmt.Fprintf(&b, "- **Exposure:** %d CVEs · %d KEV (%d ransomware) · expected exploited in 30 d **%.2f** · P(any) **%.1f%%** · grade **%s**\n\n",
		ex.Total, ex.KEV, ex.Ransomware, ex.Expected, ex.PAny*100, ex.Grade)
	b.WriteString("| CVE | Bucket | EPSS | Percentile | CVSS | Risk | KEV | Reason |\n|---|---|---|---|---|---|---|---|\n")
	for _, x := range r.Rows {
		fmt.Fprintf(&b, "| %s | %s | %s | %s | %s | %.2f | %s | %s |\n", x.CVE, x.Bucket, epssStr(x), pctStr(x), cvssStr(x.CVSS), x.Risk, kevStr(x), x.Reason)
	}
	return b.String()
}

func exportJSON(r Report) string {
	b, _ := json.MarshalIndent(r, "", "  ")
	return string(b) + "\n"
}

func exportCSV(r Report) string {
	var buf bytes.Buffer
	w := csv.NewWriter(&buf)
	w.Write([]string{"cve", "bucket", "severity", "epss", "percentile", "cvss", "risk", "kev", "kev_added", "kev_due", "ransomware", "product", "reason", "occurrences", "sla", "components", "asset", "vex"})
	for _, x := range r.Rows {
		cv := ""
		if x.CVSS >= 0 {
			cv = fmt.Sprintf("%.1f", x.CVSS)
		}
		ep, pc := "", ""
		if x.Known {
			ep, pc = fmt.Sprintf("%.5f", x.EPSS), fmt.Sprintf("%.5f", x.Percentile)
		}
		w.Write([]string{x.CVE, x.Bucket, bucketSeverity(x.Bucket), ep, pc, cv, fmt.Sprintf("%.3f", x.Risk),
			strconv.FormatBool(x.KEV), x.KEVAdded, x.KEVDue, strconv.FormatBool(x.Ransomware), x.Product, x.Reason,
			strconv.Itoa(x.Count), pol.SLA[x.Bucket], strings.Join(x.Components, " "), x.Asset, x.VEX})
	}
	w.Flush()
	return buf.String()
}

func exportSARIF(r Report) string {
	level := func(s string) string {
		switch s {
		case SevCritical, SevHigh:
			return "error"
		case SevMedium:
			return "warning"
		}
		return "note"
	}
	var rules, results []map[string]any
	for _, bk := range bucketOrder {
		rules = append(rules, map[string]any{"id": "EPSS-" + strings.ToUpper(bk), "name": bk,
			"shortDescription":     map[string]any{"text": "EPSS bucket " + bk},
			"help":                 map[string]any{"text": pol.SLA[bk]},
			"defaultConfiguration": map[string]any{"level": level(bucketSeverity(bk))}})
	}
	for _, f := range r.Findings {
		h := sha256.Sum256([]byte(f.ID))
		results = append(results, map[string]any{
			"ruleId": "EPSS-" + strings.ToUpper(f.Bucket), "level": level(f.Severity),
			"message":             map[string]any{"text": f.Title + ": " + f.Detail},
			"locations":           []any{map[string]any{"logicalLocations": []any{map[string]any{"name": f.ID, "kind": "vulnerability"}}}},
			"partialFingerprints": map[string]any{"cve": hex.EncodeToString(h[:8])},
			"properties":          map[string]any{"risk": f.Score},
		})
	}
	if results == nil {
		results = []map[string]any{}
	}
	doc := map[string]any{"$schema": "https://json.schemastore.org/sarif-2.1.0.json", "version": "2.1.0",
		"runs": []any{map[string]any{
			"tool":    map[string]any{"driver": map[string]any{"name": APPNAME, "version": VERSION, "informationUri": "https://" + WEBSITE, "rules": rules}},
			"results": results}}}
	b, _ := json.MarshalIndent(doc, "", "  ")
	return string(b) + "\n"
}

func render(r Report, format string) (string, error) {
	switch strings.ToLower(format) {
	case "", "txt", "text":
		return exportTXT(r), nil
	case "md", "markdown":
		return exportMD(r), nil
	case "json":
		return exportJSON(r), nil
	case "csv":
		return exportCSV(r), nil
	case "sarif":
		return exportSARIF(r), nil
	case "html":
		return exportHTML(r), nil
	}
	return "", fmt.Errorf("unknown format %q (txt|md|json|csv|sarif|html)", format)
}

func writeOut(content, path string) error {
	if path == "" || path == "-" {
		fmt.Print(content)
		return nil
	}
	return os.WriteFile(path, []byte(content), 0o644)
}

// ====================================================================
//  RENDERING (TUI)
// ====================================================================

func epssStr(r priorityRow) string {
	if !r.Known {
		return "-"
	}
	return fmt.Sprintf("%.4f", r.EPSS)
}
func pctStr(r priorityRow) string {
	if !r.Known {
		return "-"
	}
	return fmt.Sprintf("%.1f", r.Percentile*100)
}
func cvssStr(v float64) string {
	if v < 0 {
		return "-"
	}
	return fmt.Sprintf("%.1f", v)
}
func kevStr(r priorityRow) string {
	switch {
	case r.Ransomware:
		return "KEV+R"
	case r.KEV:
		return "KEV"
	}
	return ""
}

func printDataSources() {
	kv("EPSS data", fmt.Sprintf("%s — %d CVEs, scores %s", epssSource, len(epssDB), epssDate))
	kv("KEV data", fmt.Sprintf("%s — %d CVEs, catalog %s", kevSource, len(kevDB), kevVersion))
}

func printRows(rows []priorityRow, limit int) {
	var tr [][]string
	withComps := false
	for _, r := range rows {
		if len(r.Components) > 0 {
			withComps = true
			break
		}
	}
	for i, r := range rows {
		if limit > 0 && i >= limit {
			break
		}
		k := kevStr(r)
		switch k {
		case "KEV+R":
			k = col(k, R+B)
		case "KEV":
			k = col(k, R)
		}
		bk := bucketColor(r.Bucket)
		if vexClosed(r.VEX) {
			bk = col(r.Bucket+"·vex", DIM)
		}
		row := []string{r.CVE, bk, epssStr(r), pctStr(r), cvssStr(r.CVSS), fmt.Sprintf("%.2f", r.Risk), k}
		if withComps {
			c := ""
			if len(r.Components) > 0 {
				c = r.Components[0]
				if len(r.Components) > 1 {
					c = trunc(c, 16) + fmt.Sprintf(" +%d", len(r.Components)-1)
				}
			}
			row = append(row, trunc(c, 22))
		}
		tr = append(tr, append(row, trunc(r.Reason, 30)))
	}
	hdr := []string{"CVE", "BUCKET", "EPSS", "PCTL", "CVSS", "RISK", "KEV"}
	if withComps {
		hdr = append(hdr, "COMPONENT")
	}
	table(append(hdr, "WHY"), tr)
	if limit > 0 && len(rows) > limit {
		info(fmt.Sprintf("… %d more rows (use --limit 0 or export)", len(rows)-limit))
	}
}

func printExposure(rows []priorityRow) {
	ex := computeExposure(rows)
	fmt.Println()
	sectionHeader("Backlog Exposure")
	max := 0
	for _, b := range bucketOrder {
		if ex.Buckets[b] > max {
			max = ex.Buckets[b]
		}
	}
	for _, b := range bucketOrder {
		c := map[string]string{BucketActNow: R + B, BucketUrgent: R, BucketScheduled: OR, BucketDeferred: YLW, BucketUnknown: DIM}[b]
		fmt.Printf("  %s %5d  %s\n", pad(bucketColor(b), 10), ex.Buckets[b], bar(ex.Buckets[b], max, 36, c))
	}
	fmt.Println()
	unk := ex.Total - ex.Known - ex.VEXClosed
	kv("CVEs", fmt.Sprintf("%d total · %d scored · %d unknown", ex.Total, ex.Known, unk))
	if ex.VEXClosed > 0 {
		kv("VEX closed", fmt.Sprintf("%d not affected / resolved — excluded from exposure", ex.VEXClosed))
	}
	kev := fmt.Sprintf("%d listed", ex.KEV)
	if ex.Ransomware > 0 {
		kev += fmt.Sprintf(" · %d used by ransomware", ex.Ransomware)
	}
	kv("CISA KEV", kev)
	kv("Expected exploited", fmt.Sprintf("%.2f CVEs in the next 30 days (Σ EPSS)", ex.Expected))
	kv("P(at least one)", fmt.Sprintf("%.1f%%", ex.PAny*100))
	kv("Exposure grade", gradeColor(ex.Grade)+col(fmt.Sprintf("  (score %d/100)", ex.Score), DIM))
	if unk > 0 {
		warnMsg(fmt.Sprintf("%d CVE(s) have no score in the loaded data — try --fetch (live FIRST API) or --update.", unk))
	}
	// act-now first steps
	var top []string
	for _, r := range rows {
		if r.Bucket == BucketActNow && !vexClosed(r.VEX) && len(top) < 5 {
			top = append(top, r.CVE)
		}
	}
	if len(top) > 0 {
		fmt.Println()
		fmt.Println("  " + col("Patch first: ", R+B) + col(strings.Join(top, ", "), W))
	}
}

func printLookup(cve string) {
	r := prioritize([]cveInput{{CVE: cve, CVSS: -1}}, "priority")[0]
	kv("CVE", col(r.CVE, B+W))
	if r.Known {
		kv("EPSS", fmt.Sprintf("%.5f  (%.3f%% chance of exploitation activity in 30 days)", r.EPSS, r.EPSS*100))
		kv("Percentile", fmt.Sprintf("%.3f  (scores higher than %.1f%% of all CVEs)", r.Percentile, r.Percentile*100))
	} else {
		kv("EPSS", col("not in the loaded data", DIM))
	}
	if r.CVSS >= 0 {
		kv("CVSS", fmt.Sprintf("%.1f (%s)", r.CVSS, r.CVSSSource))
	}
	if k, ok := kevDB[r.CVE]; ok {
		v := fmt.Sprintf("listed %s · due %s", k.Added, k.Due)
		if k.Ransomware {
			v += " · " + col("known ransomware use", R+B)
		}
		kv("CISA KEV", col("YES", R+B)+"  "+v)
		if p := strings.TrimSpace(k.Vendor + " " + k.Product); p != "" {
			kv("Product", p)
		}
		if k.Name != "" {
			kv("Name", trunc(k.Name, 60))
		}
	} else {
		kv("CISA KEV", "no")
	}
	kv("Bucket", bucketColor(r.Bucket)+col("  ("+r.Reason+")", DIM))
	kv("SLA", pol.SLA[r.Bucket])
}

func printHistory(cve string, pts []histPoint) {
	if len(pts) == 0 {
		return
	}
	var ev []float64
	for _, p := range pts {
		ev = append(ev, p.EPSS)
	}
	first, last := pts[0], pts[len(pts)-1]
	kv("CVE", col(cve, B+W))
	kv("Window", fmt.Sprintf("%s → %s (%d days)", first.Date, last.Date, len(pts)))
	kv("EPSS trend", col(sparkline(ev), CY)+fmt.Sprintf("  %.4f → %.4f", first.EPSS, last.EPSS))
	d := last.EPSS - first.EPSS
	dir := col(fmt.Sprintf("%+.4f", d), DIM)
	switch {
	case d >= 0.05:
		dir = col(fmt.Sprintf("%+.4f  rising sharply", d), R+B)
	case d > 0:
		dir = col(fmt.Sprintf("%+.4f  rising", d), OR)
	case d < 0:
		dir = col(fmt.Sprintf("%+.4f  falling", d), GRN)
	}
	kv("Change", dir)
	lo, hi := ev[0], ev[0]
	for _, v := range ev {
		lo, hi = math.Min(lo, v), math.Max(hi, v)
	}
	kv("Range", fmt.Sprintf("%.4f – %.4f", lo, hi))
	fmt.Println()
	var rows [][]string
	for i := len(pts) - 1; i >= 0 && len(rows) < 10; i-- {
		rows = append(rows, []string{pts[i].Date, fmt.Sprintf("%.5f", pts[i].EPSS), fmt.Sprintf("%.1f", pts[i].Percentile*100)})
	}
	table([]string{"DATE", "EPSS", "PCTL"}, rows)
}

func printTune() {
	rows, total, kevScored := tuneThresholds()
	kv("Population", fmt.Sprintf("%d scored CVEs (%s)", total, epssSource))
	kv("Ground truth", fmt.Sprintf("%d KEV CVEs that have an EPSS score", kevScored))
	if total < 100000 {
		warnMsg("Only the embedded snapshot is loaded — it is biased toward high-EPSS CVEs.")
		warnMsg("Run --update for the full daily dataset before trusting these numbers.")
	}
	fmt.Println()
	best := 0
	for i, r := range rows {
		if r.F1 > rows[best].F1 {
			best = i
		}
	}
	var tr [][]string
	for i, r := range rows {
		mark := ""
		if i == best {
			mark = col("◀ best F1", GRN+B)
		}
		tr = append(tr, []string{fmt.Sprintf("%.3f", r.Threshold), strconv.Itoa(r.Flagged),
			fmt.Sprintf("%.2f%%", r.Effort*100), fmt.Sprintf("%.1f%%", r.Coverage*100),
			fmt.Sprintf("%.1f%%", r.Efficiency*100), fmt.Sprintf("%.3f", r.F1), mark})
	}
	table([]string{"EPSS ≥", "FLAGGED", "EFFORT", "COVERAGE", "EFFICIENCY", "F1", ""}, tr)
	fmt.Println()
	info("effort = share of all CVEs you would patch · coverage = share of KEV you would catch")
	info("efficiency = share of patched CVEs that are KEV. KEV is a lower bound on exploitation.")
}

// ====================================================================
//  SBOM INPUT: CycloneDX (vulnerabilities + VEX) and SPDX
// ====================================================================

func str(v any) string { s, _ := v.(string); return s }

// pkgOf names the package an object describes (Trivy, Grype, OSV shapes).
func pkgOf(m map[string]any) string {
	join := func(n, v string) string {
		if n == "" {
			return ""
		}
		if v != "" {
			return n + "@" + v
		}
		return n
	}
	if n := str(m["PkgName"]); n != "" {
		return join(n, str(m["InstalledVersion"]))
	}
	for _, k := range []string{"artifact", "package"} {
		if a, ok := m[k].(map[string]any); ok {
			if n := str(a["name"]); n != "" {
				return join(n, str(a["version"]))
			}
		}
	}
	return ""
}

// extractSBOM recognises CycloneDX and SPDX JSON documents. kind names the
// format for messages; ok is false for anything else (or an SBOM without
// CVE references), so the caller falls back to the generic JSON walker.
func extractSBOM(data []byte) (in []cveInput, kind string, ok bool) {
	var doc map[string]any
	if json.Unmarshal(data, &doc) != nil {
		return nil, "", false
	}
	switch {
	case strings.EqualFold(str(doc["bomFormat"]), "CycloneDX"):
		in = extractCycloneDX(doc)
		kind = "CycloneDX " + str(doc["specVersion"])
	case str(doc["spdxVersion"]) != "":
		in = extractSPDX(doc)
		kind = str(doc["spdxVersion"])
	default:
		return nil, "", false
	}
	return in, kind, len(in) > 0
}

func extractCycloneDX(doc map[string]any) []cveInput {
	comps := map[string]string{} // bom-ref → name@version
	var addComps func(v any)
	addComps = func(v any) {
		arr, _ := v.([]any)
		for _, x := range arr {
			c, ok := x.(map[string]any)
			if !ok {
				continue
			}
			name := str(c["name"])
			if g := str(c["group"]); g != "" {
				name = g + "/" + name
			}
			if v := str(c["version"]); v != "" {
				name += "@" + v
			}
			if ref := str(c["bom-ref"]); ref != "" && name != "" {
				comps[ref] = name
			}
			addComps(c["components"])
		}
	}
	addComps(doc["components"])
	if md, ok := doc["metadata"].(map[string]any); ok {
		addComps([]any{md["component"]})
	}
	var sets [][]cveInput
	vulns, _ := doc["vulnerabilities"].([]any)
	for _, x := range vulns {
		v, ok := x.(map[string]any)
		if !ok {
			continue
		}
		// the id may be a GHSA / OSV id with the CVE among its references
		var ids []string
		if c := normCVE(str(v["id"])); c != "" {
			ids = append(ids, c)
		}
		refs, _ := v["references"].([]any)
		for _, r := range refs {
			if rm, ok := r.(map[string]any); ok {
				if c := normCVE(str(rm["id"])); c != "" {
					ids = addUniq(ids, c)
				}
			}
		}
		if len(ids) == 0 {
			continue
		}
		score := -1.0
		ratings, _ := v["ratings"].([]any)
		for _, r := range ratings {
			if rm, ok := r.(map[string]any); ok {
				if f, ok := rm["score"].(float64); ok && f >= 0 && f <= 10 && f > score &&
					strings.Contains(strings.ToUpper(str(rm["method"])+"CVSS"), "CVSS") {
					score = f
				}
			}
		}
		var affected []string
		aff, _ := v["affects"].([]any)
		for _, a := range aff {
			if am, ok := a.(map[string]any); ok {
				ref := str(am["ref"])
				if n, ok := comps[ref]; ok {
					ref = n
				}
				affected = addUniq(affected, ref)
			}
		}
		state := ""
		if an, ok := v["analysis"].(map[string]any); ok {
			state = str(an["state"])
		}
		var set []cveInput
		for _, c := range ids {
			set = append(set, cveInput{CVE: c, CVSS: score, Count: 1, Comps: affected, VEX: state})
		}
		sets = append(sets, set)
	}
	return mergeInputs(sets...)
}

// extractSPDX maps CVE ids found anywhere inside a package (externalRefs of
// category SECURITY, annotations, comments) to that package.
func extractSPDX(doc map[string]any) []cveInput {
	var sets [][]cveInput
	pkgs, _ := doc["packages"].([]any)
	for _, x := range pkgs {
		p, ok := x.(map[string]any)
		if !ok {
			continue
		}
		name := str(p["name"])
		if v := str(p["versionInfo"]); v != "" {
			name += "@" + v
		}
		b, _ := json.Marshal(p)
		var set []cveInput
		for _, c := range extractCVEs(string(b)) {
			set = append(set, cveInput{CVE: c.CVE, CVSS: -1, Count: 1, Comps: addUniq(nil, name)})
		}
		sets = append(sets, set)
	}
	return mergeInputs(sets...)
}

// ====================================================================
//  ASSET CONTEXT (--assets FILE)
// ====================================================================

// assetRule: hosts / images / packages matching pattern get their bucket
// moved by criticality and network exposure, and their risk weighted.
type assetRule struct {
	pattern, crit, expo string
	adj                 int
	weight              float64
}

var assetRules []assetRule

var (
	critAdj  = map[string]int{"low": -1, "medium": 0, "high": 0, "critical": 1}
	critW    = map[string]float64{"low": 0.5, "medium": 1, "high": 1.5, "critical": 2}
	expoAdj  = map[string]int{"isolated": -1, "internal": 0, "internet": 1, "dmz": 1}
	expoW    = map[string]float64{"isolated": 0.5, "internal": 1, "internet": 1.5, "dmz": 1.5}
	rankName = map[int]string{5: BucketActNow, 4: BucketUrgent, 3: BucketScheduled, 2: BucketDeferred}
)

// parseAssets reads "pattern, criticality[, exposure]" lines (comma, tab or
// space separated; # comments). Patterns are case-insensitive globs.
func parseAssets(text string) ([]assetRule, error) {
	var out []assetRule
	for i, ln := range strings.Split(text, "\n") {
		if j := strings.Index(ln, "#"); j >= 0 {
			ln = ln[:j]
		}
		f := strings.FieldsFunc(ln, func(r rune) bool { return r == ',' || r == '\t' || r == ' ' || r == ';' })
		if len(f) == 0 {
			continue
		}
		if len(f) < 2 {
			return nil, fmt.Errorf("assets line %d: want PATTERN,CRITICALITY[,EXPOSURE]", i+1)
		}
		if i == 0 && strings.EqualFold(f[0], "pattern") {
			continue // header row
		}
		r := assetRule{pattern: strings.ToLower(f[0]), crit: strings.ToLower(f[1]), expo: "internal"}
		if len(f) > 2 {
			r.expo = strings.ToLower(f[2])
		}
		ca, ok1 := critAdj[r.crit]
		ea, ok2 := expoAdj[r.expo]
		if !ok1 || !ok2 {
			return nil, fmt.Errorf("assets line %d: criticality low|medium|high|critical, exposure isolated|internal|internet|dmz", i+1)
		}
		if _, err := filepath.Match(r.pattern, ""); err != nil {
			return nil, fmt.Errorf("assets line %d: bad pattern %q", i+1, f[0])
		}
		r.adj = max(-2, min(2, ca+ea))
		r.weight = critW[r.crit] * expoW[r.expo]
		out = append(out, r)
	}
	return out, nil
}

func loadAssets(path string) (int, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return 0, err
	}
	rules, err := parseAssets(string(data))
	if err != nil {
		return 0, err
	}
	assetRules = rules
	return len(rules), nil
}

// matchAsset returns the most severe rule matching any of the row's tokens
// or components (a component also matches by its bare name, without @version).
func matchAsset(r priorityRow) (assetRule, string, bool) {
	var cands []string
	for _, t := range r.tokens {
		cands = append(cands, strings.ToLower(t))
	}
	for _, c := range r.Components {
		c = strings.ToLower(c)
		cands = append(cands, c)
		if n, _, ok := strings.Cut(c, "@"); ok {
			cands = append(cands, n)
		}
	}
	var best assetRule
	who, found := "", false
	for _, ar := range assetRules {
		for _, c := range cands {
			if ok, _ := filepath.Match(ar.pattern, c); !ok {
				continue
			}
			if !found || ar.adj > best.adj || ar.adj == best.adj && ar.weight > best.weight {
				best, who, found = ar, c, true
			}
		}
	}
	return best, who, found
}

// applyAsset shifts the bucket by the asset's steps. Never into or out of
// "unknown", never below deferred, and a KEV act-now is never demoted.
func applyAsset(r *priorityRow) {
	if len(assetRules) == 0 {
		return
	}
	ar, who, ok := matchAsset(*r)
	if !ok {
		return
	}
	r.Asset = fmt.Sprintf("%s (%s, %s)", who, ar.crit, ar.expo)
	r.Risk = math.Min(10, r.Risk*ar.weight) // stays on the 0..10 scale
	if r.Bucket == BucketUnknown || ar.adj == 0 || r.KEV && pol.KEVActNow && ar.adj < 0 {
		return
	}
	nr := max(2, min(5, bucketRank[r.Bucket]+ar.adj))
	if moved := nr - bucketRank[r.Bucket]; moved != 0 {
		r.AssetAdj = moved
		r.Bucket = rankName[nr]
		r.Reason += fmt.Sprintf(" · asset %s %+d", who, moved)
	}
}

// ====================================================================
//  DIFF: compare two scans
// ====================================================================

type diffRow struct {
	CVE    string       `json:"cve"`
	Change string       `json:"change"`
	Old    *priorityRow `json:"old,omitempty"`
	New    *priorityRow `json:"new,omitempty"`
}

type diffReport struct {
	Tool      string         `json:"tool"`
	Version   string         `json:"version"`
	Generated string         `json:"generated"`
	OldLabel  string         `json:"old"`
	NewLabel  string         `json:"new"`
	OldExp    exposure       `json:"old_exposure"`
	NewExp    exposure       `json:"new_exposure"`
	Counts    map[string]int `json:"counts"`
	Rows      []diffRow      `json:"changes"`
}

// change kinds, most important first
var diffOrder = []string{"newly-kev", "new", "escalated", "epss-up", "de-escalated", "epss-down", "vex-closed", "fixed"}

var diffColor = map[string]string{"newly-kev": R + B, "new": OR, "escalated": R, "epss-up": YLW,
	"de-escalated": GRN, "epss-down": GRN, "vex-closed": GRN, "fixed": GRN + B}

// loadSide reads one side of a diff. A saved OEPSS JSON report keeps the
// scores it was produced with (that is what makes a diff over time mean
// something); any other input is scored against the data loaded now.
func loadSide(paths []string, cves string) ([]priorityRow, string, error) {
	if len(paths) == 1 && cves == "" {
		data, err := os.ReadFile(paths[0])
		if err != nil {
			return nil, "", err
		}
		var rep Report
		if json.Unmarshal(data, &rep) == nil && rep.Tool == APPNAME && rep.Rows != nil {
			return rep.Rows, fmt.Sprintf("%s (report %s, EPSS %s)", paths[0], rep.Generated[:min(10, len(rep.Generated))], rep.EPSSDate), nil
		}
	}
	sets := [][]cveInput{extractCVEs(strings.ReplaceAll(cves, ",", " "))}
	for _, p := range paths {
		data, err := os.ReadFile(p)
		if err != nil {
			return nil, "", err
		}
		sets = append(sets, extractAny(data))
	}
	label := strings.Join(paths, ", ")
	if cves != "" {
		label = strings.TrimPrefix(label+", --cve", ", ")
	}
	return prioritize(mergeInputs(sets...), "priority"), label + " (scored now)", nil
}

const epssMove = 0.05 // EPSS change worth reporting when the bucket is unchanged

func diffScans(oldRows, newRows []priorityRow, oldLabel, newLabel string) diffReport {
	d := diffReport{Tool: APPNAME, Version: VERSION, Generated: time.Now().UTC().Format(time.RFC3339),
		OldLabel: oldLabel, NewLabel: newLabel, OldExp: computeExposure(oldRows), NewExp: computeExposure(newRows),
		Counts: map[string]int{}, Rows: []diffRow{}}
	om := map[string]*priorityRow{}
	for i := range oldRows {
		om[oldRows[i].CVE] = &oldRows[i]
	}
	seen := map[string]bool{}
	for i := range newRows {
		n := &newRows[i]
		seen[n.CVE] = true
		o, ok := om[n.CVE]
		ch := ""
		switch {
		case !ok:
			ch = "new"
		case vexClosed(n.VEX) && !vexClosed(o.VEX):
			ch = "vex-closed"
		case n.KEV && !o.KEV:
			ch = "newly-kev"
		case bucketRank[n.Bucket] > bucketRank[o.Bucket]:
			ch = "escalated"
		case bucketRank[n.Bucket] < bucketRank[o.Bucket]:
			ch = "de-escalated"
		case n.EPSS-o.EPSS >= epssMove:
			ch = "epss-up"
		case o.EPSS-n.EPSS >= epssMove:
			ch = "epss-down"
		}
		if ch != "" {
			d.Rows = append(d.Rows, diffRow{n.CVE, ch, o, n})
		}
	}
	for i := range oldRows {
		if !seen[oldRows[i].CVE] {
			d.Rows = append(d.Rows, diffRow{oldRows[i].CVE, "fixed", &oldRows[i], nil})
		}
	}
	rank := map[string]int{}
	for i, k := range diffOrder {
		rank[k] = i
	}
	sort.SliceStable(d.Rows, func(i, j int) bool {
		a, b := d.Rows[i], d.Rows[j]
		if rank[a.Change] != rank[b.Change] {
			return rank[a.Change] < rank[b.Change]
		}
		ra, rb := a.New, b.New
		if ra == nil || rb == nil {
			return a.CVE < b.CVE
		}
		if bucketRank[ra.Bucket] != bucketRank[rb.Bucket] {
			return bucketRank[ra.Bucket] > bucketRank[rb.Bucket]
		}
		return ra.EPSS > rb.EPSS
	})
	for _, r := range d.Rows {
		d.Counts[r.Change]++
	}
	return d
}

// diffAlarming: something new or worse now sits in act-now.
func diffAlarming(d diffReport) bool {
	for _, r := range d.Rows {
		if r.New != nil && r.New.Bucket == BucketActNow && !vexClosed(r.New.VEX) &&
			(r.Change == "new" || r.Change == "newly-kev" || r.Change == "escalated") {
			return true
		}
	}
	return false
}

func sideStr(r *priorityRow) string {
	if r == nil {
		return "—"
	}
	s := r.Bucket + " " + epssStr(*r)
	if r.KEV {
		s += " KEV"
	}
	return s
}

func printDiff(d diffReport, limit int) {
	sectionHeader("Scan Diff")
	kv("Old", d.OldLabel)
	kv("New", d.NewLabel)
	var cs []string
	for _, k := range diffOrder {
		cs = append(cs, col(fmt.Sprintf("%s %d", k, d.Counts[k]), diffColor[k]))
	}
	kv("Changes", strings.Join(cs, col(" · ", DIM)))
	o, n := d.OldExp, d.NewExp
	kv("Act-now", fmt.Sprintf("%d → %d", o.Buckets[BucketActNow], n.Buckets[BucketActNow]))
	kv("Expected exploited", fmt.Sprintf("%.2f → %.2f  (%+.2f)", o.Expected, n.Expected, n.Expected-o.Expected))
	kv("P(at least one)", fmt.Sprintf("%.1f%% → %.1f%%", o.PAny*100, n.PAny*100))
	kv("Exposure grade", gradeColor(o.Grade)+col(" → ", DIM)+gradeColor(n.Grade))
	fmt.Println()
	if len(d.Rows) == 0 {
		okMsg("No changes between the two scans.")
		return
	}
	var tr [][]string
	for i, r := range d.Rows {
		if limit > 0 && i >= limit {
			break
		}
		why := ""
		if r.New != nil {
			why = r.New.Reason
		}
		tr = append(tr, []string{r.CVE, col(r.Change, diffColor[r.Change]), sideStr(r.Old), sideStr(r.New), trunc(why, 30)})
	}
	table([]string{"CVE", "CHANGE", "BEFORE", "NOW", "WHY"}, tr)
	if limit > 0 && len(d.Rows) > limit {
		info(fmt.Sprintf("… %d more changes (use --limit 0 or export)", len(d.Rows)-limit))
	}
}

func renderDiff(d diffReport, format string) (string, error) {
	var b strings.Builder
	switch strings.ToLower(format) {
	case "json":
		j, _ := json.MarshalIndent(d, "", "  ")
		return string(j) + "\n", nil
	case "csv":
		w := csv.NewWriter(&b)
		w.Write([]string{"cve", "change", "old_bucket", "old_epss", "old_kev", "new_bucket", "new_epss", "new_kev", "reason"})
		for _, r := range d.Rows {
			rec := []string{r.CVE, r.Change, "", "", "", "", "", "", ""}
			if r.Old != nil {
				rec[2], rec[3], rec[4] = r.Old.Bucket, fmt.Sprintf("%.5f", r.Old.EPSS), strconv.FormatBool(r.Old.KEV)
			}
			if r.New != nil {
				rec[5], rec[6], rec[7], rec[8] = r.New.Bucket, fmt.Sprintf("%.5f", r.New.EPSS), strconv.FormatBool(r.New.KEV), r.New.Reason
			}
			w.Write(rec)
		}
		w.Flush()
		return b.String(), nil
	case "md", "markdown":
		fmt.Fprintf(&b, "# %s — scan diff\n\n- **Old:** %s\n- **New:** %s\n- **Act-now:** %d → %d\n- **Expected exploited (30 d):** %.2f → %.2f\n- **Grade:** %s → %s\n\n",
			APPNAME, d.OldLabel, d.NewLabel, d.OldExp.Buckets[BucketActNow], d.NewExp.Buckets[BucketActNow],
			d.OldExp.Expected, d.NewExp.Expected, d.OldExp.Grade, d.NewExp.Grade)
		b.WriteString("| CVE | Change | Before | Now |\n|---|---|---|---|\n")
		for _, r := range d.Rows {
			fmt.Fprintf(&b, "| %s | %s | %s | %s |\n", r.CVE, r.Change, sideStr(r.Old), sideStr(r.New))
		}
		return b.String(), nil
	case "", "txt", "text":
		fmt.Fprintf(&b, "%s v%s — scan diff\nOld: %s\nNew: %s\n", APPNAME, VERSION, d.OldLabel, d.NewLabel)
		fmt.Fprintf(&b, "Act-now %d -> %d · expected exploited %.2f -> %.2f · grade %s -> %s\n%s\n",
			d.OldExp.Buckets[BucketActNow], d.NewExp.Buckets[BucketActNow], d.OldExp.Expected, d.NewExp.Expected,
			d.OldExp.Grade, d.NewExp.Grade, strings.Repeat("-", 66))
		for _, r := range d.Rows {
			fmt.Fprintf(&b, "%-18s %-13s %-28s %s\n", r.CVE, r.Change, sideStr(r.Old), sideStr(r.New))
		}
		return b.String(), nil
	}
	return "", fmt.Errorf("diff format %q: txt|md|json|csv", format)
}

// ====================================================================
