var bucketHex = map[string]string{BucketActNow: "#d03b3b", BucketUrgent: "#ec835a", BucketScheduled: "#fab219",
	BucketDeferred: "#0ca30c", BucketUnknown: "#8a8984"}

// exportHTML writes one self-contained page (no external resources): stat
// tiles, bucket and EPSS-band bar charts with hover values, and a sortable,
// filterable table. Light and dark themes follow the viewer's preference.
func exportHTML(r Report) string {
	e := html.EscapeString
	ex := r.Exposure
	var b strings.Builder
	b.WriteString(`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>OEPSS Report</title><style>
:root{--bg:#f4f4f2;--surface:#fcfcfb;--ink:#0b0b0b;--ink2:#52514e;--muted:#8a8984;--line:#e2e1dc;--brand:#0e7c86;--seq:#2a78d6;--chip:#efeeea}
@media (prefers-color-scheme:dark){:root{--bg:#111110;--surface:#1a1a19;--ink:#f0efec;--ink2:#c3c2b7;--muted:#8a8984;--line:#2e2e2b;--brand:#3fc1cc;--seq:#3987e5;--chip:#262624}}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.45 system-ui,-apple-system,"Segoe UI",sans-serif}
main{max-width:1180px;margin:0 auto;padding:24px 16px 48px}
header h1{margin:0;font-size:22px;letter-spacing:.2px}header h1 span{color:var(--brand)}
.meta{color:var(--ink2);font-size:13px;margin:6px 0 20px}.meta b{color:var(--ink);font-weight:600}
.tiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px;margin-bottom:20px}
.tile{background:var(--surface);border:1px solid var(--line);border-radius:10px;padding:14px 16px}
.tile .k{color:var(--ink2);font-size:12px;text-transform:uppercase;letter-spacing:.6px}.tile .v{font-size:26px;font-weight:650;margin-top:4px;font-variant-numeric:tabular-nums}
.tile .s{color:var(--muted);font-size:12px}
.charts{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:12px;margin-bottom:20px}
.card{background:var(--surface);border:1px solid var(--line);border-radius:10px;padding:16px}
.card h2{margin:0 0 12px;font-size:14px;font-weight:600}
.bar{display:grid;grid-template-columns:96px 1fr 48px;align-items:center;gap:10px;margin:6px 0;font-size:13px}
.bar .lab{color:var(--ink2);display:flex;align-items:center;gap:6px}.bar .num{text-align:right;font-variant-numeric:tabular-nums;color:var(--ink)}
.track{height:14px;position:relative}.fill{height:100%;border-radius:0 4px 4px 0;min-width:2px}
.dot{width:9px;height:9px;border-radius:50%;display:inline-block;flex:none}
.tools{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:10px}
.tools input,.tools select{background:var(--surface);color:var(--ink);border:1px solid var(--line);border-radius:8px;padding:7px 10px;font:inherit}
.tools input{flex:1;min-width:180px}
.tablewrap{overflow-x:auto;background:var(--surface);border:1px solid var(--line);border-radius:10px}
table{border-collapse:collapse;width:100%;font-size:13px}th,td{padding:8px 10px;text-align:left;border-bottom:1px solid var(--line);white-space:nowrap}
th{position:sticky;top:0;background:var(--surface);color:var(--ink2);font-weight:600;cursor:pointer;user-select:none}th:hover{color:var(--ink)}
td.n{text-align:right;font-variant-numeric:tabular-nums}td.why{white-space:normal;color:var(--ink2);min-width:220px}
tr.closed td{opacity:.55}a{color:var(--brand);text-decoration:none}a:hover{text-decoration:underline}
.chip{display:inline-flex;align-items:center;gap:6px;background:var(--chip);border-radius:999px;padding:2px 9px;font-size:12px}
.kev{font-weight:650;color:#d03b3b}
#tip{position:fixed;pointer-events:none;background:var(--ink);color:var(--surface);font-size:12px;padding:6px 9px;border-radius:6px;opacity:0;transition:opacity .08s;z-index:9}
footer{color:var(--muted);font-size:12px;margin-top:20px}
</style></head><body><main>
`)
	fmt.Fprintf(&b, `<header><h1><span>OEPSS</span> — CVE prioritisation</h1><div class="meta"><b>%s</b> · generated %s<br>EPSS: %s (scores %s) · KEV: %s (catalog %s) · policy <code>%s</code></div></header>
`, e(r.Target), e(r.Generated), e(r.EPSSSource), e(r.EPSSDate), e(r.KEVSource), e(r.KEVVersion), e(r.Policy))
	tile := func(k, v, s string) {
		fmt.Fprintf(&b, `<div class="tile"><div class="k">%s</div><div class="v">%s</div><div class="s">%s</div></div>`, k, v, s)
	}
	b.WriteString(`<section class="tiles">`)
	tile("CVEs", strconv.Itoa(ex.Total), fmt.Sprintf("%d scored · %d VEX-closed", ex.Known, ex.VEXClosed))
	tile("Act now", strconv.Itoa(ex.Buckets[BucketActNow]), fmt.Sprintf("%d urgent · %d scheduled", ex.Buckets[BucketUrgent], ex.Buckets[BucketScheduled]))
	tile("CISA KEV", strconv.Itoa(ex.KEV), fmt.Sprintf("%d used by ransomware", ex.Ransomware))
	tile("Expected exploited", fmt.Sprintf("%.2f", ex.Expected), "CVEs in 30 days (Σ EPSS)")
	tile("P(at least one)", fmt.Sprintf("%.1f%%", ex.PAny*100), "1 − Π(1 − EPSS)")
	tile("Exposure grade", e(ex.Grade), fmt.Sprintf("score %d/100", ex.Score))
	b.WriteString("</section>\n<section class=\"charts\">")

	bars := func(title string, labels []string, vals []int, colors []string, dots bool) {
		mx := 1
		for _, v := range vals {
			mx = max(mx, v)
		}
		fmt.Fprintf(&b, `<div class="card"><h2>%s</h2>`, title)
		for i, l := range labels {
			dot := ""
			if dots {
				dot = fmt.Sprintf(`<span class="dot" style="background:%s"></span>`, colors[i])
			}
			fill := ""
			if vals[i] > 0 { // no stub for zero: an empty track reads as zero
				fill = fmt.Sprintf(`<span class="fill" style="display:block;width:%.1f%%;background:%s"></span>`, float64(vals[i])*100/float64(mx), colors[i])
			}
			fmt.Fprintf(&b, `<div class="bar" data-tip="%s: %d CVE(s)"><span class="lab">%s%s</span><span class="track">%s</span><span class="num">%d</span></div>`,
				e(l), vals[i], dot, e(l), fill, vals[i])
		}
		b.WriteString("</div>")
	}
	var bl []string
	var bv []int
	var bc []string
	for _, k := range bucketOrder {
		bl, bv, bc = append(bl, k), append(bv, ex.Buckets[k]), append(bc, bucketHex[k])
	}
	bars("Remediation buckets (open CVEs)", bl, bv, bc, true)
	var hl []string
	hv := make([]int, len(epssBands))
	var hc []string
	for _, band := range epssBands {
		hl, hc = append(hl, band.Label), append(hc, "var(--seq)")
	}
	for _, x := range r.Rows {
		if !x.Known {
			continue
		}
		for i, band := range epssBands {
			if x.EPSS >= band.Lo && x.EPSS < band.Hi {
				hv[i]++
				break
			}
		}
	}
	bars("EPSS distribution (scored CVEs)", hl, hv, hc, false)
	b.WriteString("</section>\n")

	b.WriteString(`<section><div class="tools"><input id="q" type="search" placeholder="Filter CVE, component, asset, reason…" aria-label="Filter"><select id="bk" aria-label="Bucket"><option value="">All buckets</option>`)
	for _, k := range bucketOrder {
		fmt.Fprintf(&b, `<option>%s</option>`, k)
	}
	b.WriteString(`</select></div><div class="tablewrap"><table id="t"><thead><tr><th data-k="s">CVE</th><th data-k="r">Bucket</th><th data-k="n">EPSS</th><th data-k="n">Pctl</th><th data-k="n">CVSS</th><th data-k="n">Risk</th><th data-k="s">KEV</th><th data-k="s">Components</th><th data-k="s">Asset</th><th data-k="s">Why</th></tr></thead><tbody>`)
	for _, x := range r.Rows {
		cls := ""
		if vexClosed(x.VEX) {
			cls = ` class="closed"`
		}
		kev := ""
		if x.KEV {
			kev = `<span class="kev">KEV</span>`
			if x.Ransomware {
				kev = `<span class="kev">KEV · ransomware</span>`
			}
		}
		bk := x.Bucket
		if vexClosed(x.VEX) {
			bk += " (VEX " + x.VEX + ")"
		}
		fmt.Fprintf(&b, `<tr%s data-b="%s"><td><a href="https://nvd.nist.gov/vuln/detail/%s" rel="noopener">%s</a></td><td data-v="%d"><span class="chip"><span class="dot" style="background:%s"></span>%s</span></td><td class="n">%s</td><td class="n">%s</td><td class="n">%s</td><td class="n">%.2f</td><td>%s</td><td>%s</td><td>%s</td><td class="why">%s</td></tr>`,
			cls, x.Bucket, x.CVE, x.CVE, bucketRank[x.Bucket], bucketHex[x.Bucket], e(bk), epssStr(x), pctStr(x), cvssStr(x.CVSS), x.Risk,
			kev, e(strings.Join(x.Components, ", ")), e(x.Asset), e(x.Reason))
	}
	b.WriteString(`</tbody></table></div></section>
<footer>OEPSS v` + VERSION + ` · Owl Vuln Intel Suite · owlsec.org — EPSS is the probability of exploitation activity in the next 30 days; KEV is CISA's known-exploited catalog.</footer>
</main><div id="tip" role="tooltip"></div><script>
(function(){
var tip=document.getElementById('tip');
document.querySelectorAll('[data-tip]').forEach(function(el){
 el.addEventListener('mousemove',function(ev){tip.textContent=el.getAttribute('data-tip');tip.style.left=(ev.clientX+12)+'px';tip.style.top=(ev.clientY+12)+'px';tip.style.opacity=1});
 el.addEventListener('mouseleave',function(){tip.style.opacity=0});});
var tb=document.querySelector('#t tbody'),q=document.getElementById('q'),bk=document.getElementById('bk');
function filt(){var s=q.value.toLowerCase(),b=bk.value;Array.prototype.forEach.call(tb.rows,function(r){
 r.style.display=(!s||r.textContent.toLowerCase().indexOf(s)>=0)&&(!b||r.getAttribute('data-b')===b)?'':'none';});}
q.addEventListener('input',filt);bk.addEventListener('change',filt);
document.querySelectorAll('#t th').forEach(function(th,i){var asc=false;th.addEventListener('click',function(){
 asc=!asc;var k=th.getAttribute('data-k');var rows=Array.prototype.slice.call(tb.rows);
 rows.sort(function(a,b){var x=a.cells[i],y=b.cells[i],u,v;
  if(k==='r'){u=+x.getAttribute('data-v');v=+y.getAttribute('data-v');}
  else if(k==='n'){u=parseFloat(x.textContent);v=parseFloat(y.textContent);if(isNaN(u))u=-1;if(isNaN(v))v=-1;}
  else{u=x.textContent;v=y.textContent;return asc?u.localeCompare(v):v.localeCompare(u);}
  return asc?u-v:v-u;});
 rows.forEach(function(r){tb.appendChild(r)});});});
})();
</script></body></html>
`)
	return b.String()
}

